	// The MSB (position k-1) must be 1.
	// We need exactly one zero among all k bits.
	// Since MSB is 1, the zero must be at some position i where 0 <= i <= k-2.
	// So the number = (2^k - 1) - 2^i for i in [0, k-2]

	// But we also need to consider numbers with fewer bits.
	// For a number with exactly m bits (m >= 1):
	// If m = 1: the number is 1 (binary "1"), which has zero zeros. Not counted.
	// If m >= 2: the number has exactly one zero, so it's (2^m - 1) - 2^i for i in [0, m-2]

	// So we need to count all such numbers <= n.

	var count int64 = 0

	// For each possible bit length m from 2 to length:
	for m := int64(2); m <= int64(length); m++ {
		// For this bit length m, the numbers are (2^m - 1) - 2^i for i in [0, m-2]
		// The smallest such number is when i = m-2: (2^m - 1) - 2^(m-2)
		// The largest such number is when i = 0: (2^m - 1) - 1 = 2^m - 2

